export type UpgradeRun = {
  projectType?: string
  toolkit?: string
  theme?: string
  sourceVersion?: string
  sourceRoot?: string
  targetRoot?: string
  lintFolders?: number
  lintFilesFixed?: number
  lintFoldersFailed?: number
  serverUrl?: string
}

export type UpgradeStep = {
